-- Hiring board: companies, open roles, and per-locale copy.
-- Timestamps are Unix milliseconds in UTC. A job is listed while status = 'open'
-- and expires_at is NULL or in the future. Pinned jobs (sponsors) sort first.
-- Translations fall back to en, then zh, when a locale row is missing.
CREATE TABLE IF NOT EXISTS job_companies (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  website_url   TEXT,
  logo_url      TEXT,
  careers_url   TEXT,
  is_sponsor    INTEGER NOT NULL DEFAULT 0 CHECK (is_sponsor IN (0, 1)),
  display_order INTEGER NOT NULL DEFAULT 0,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS jobs (
  id               TEXT PRIMARY KEY,
  company_id       TEXT NOT NULL REFERENCES job_companies(id),
  apply_url        TEXT NOT NULL,
  -- Comma-separated subset of full_time, intern, part_time.
  employment_types TEXT NOT NULL DEFAULT 'full_time',
  status           TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  is_pinned        INTEGER NOT NULL DEFAULT 0 CHECK (is_pinned IN (0, 1)),
  display_order    INTEGER NOT NULL DEFAULT 0,
  expires_at       INTEGER,
  created_at       INTEGER NOT NULL,
  updated_at       INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_jobs_listing
  ON jobs(status, is_pinned DESC, display_order);

CREATE TABLE IF NOT EXISTS job_translations (
  job_id   TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  locale   TEXT NOT NULL,
  title    TEXT NOT NULL,
  category TEXT,
  location TEXT,
  salary   TEXT,
  summary  TEXT,
  PRIMARY KEY (job_id, locale)
);



