INSERT INTO job_translations (job_id, locale, title, category, location, salary, summary) VALUES
  ('modaleap-agent-engineer', 'en', 'Agent R&D Engineer', 'R&D', NULL, NULL, 'Build AI-driven tools, model evaluation and full-stack product capabilities, shipping to users and iterating continuously.'),
  ('modaleap-agent-engineer', 'zh', 'Agent 研发工程师', '研发', NULL, NULL, '参与 AI 驱动工具、模型评测与全栈产品能力建设，直接面向用户持续迭代。'),
  ('modaleap-agent-engineer', 'ja', 'Agent 開発エンジニア', '研究開発', NULL, NULL, 'AI 駆動ツール、モデル評価、フルスタックのプロダクト開発に携わり、ユーザーと向き合いながら改善を重ねます。'),
  ('modaleap-agent-engineer', 'ko', 'Agent 개발 엔지니어', '연구개발', NULL, NULL, 'AI 기반 도구, 모델 평가, 풀스택 제품 역량 구축에 참여하며 사용자와 직접 마주하고 지속적으로 개선합니다.'),
  ('modaleap-agent-engineer', 'es', 'Ingeniero de I+D de agentes', 'I+D', NULL, NULL, 'Construye herramientas impulsadas por IA, evaluación de modelos y producto full-stack, iterando de cara al usuario.'),
  ('modaleap-agent-engineer', 'pt', 'Engenheiro de P&D de agentes', 'P&D', NULL, NULL, 'Construa ferramentas movidas a IA, avaliação de modelos e produto full-stack, iterando direto com os usuários.'),
  ('modaleap-agent-engineer', 'id', 'Engineer R&D Agent', 'R&D', NULL, NULL, 'Membangun tool berbasis AI, evaluasi model, dan kapabilitas produk full-stack yang langsung dipakai pengguna.'),
  ('modaleap-agent-engineer', 'vi', 'Kỹ sư R&D Agent', 'R&D', NULL, NULL, 'Xây dựng công cụ dùng AI, đánh giá mô hình và năng lực sản phẩm full-stack, liên tục cải tiến cùng người dùng.'),
  ('modaleap-agent-engineer', 'ar', 'مهندس بحث وتطوير الوكلاء', 'البحث والتطوير', NULL, NULL, 'المشاركة في بناء أدوات مدعومة بالذكاء الاصطناعي وتقييم النماذج وقدرات المنتج المتكاملة مع تطوير مستمر يخدم المستخدمين مباشرة.'),
  ('modaleap-fde-delivery-engineer', 'en', 'Forward Deployed Engineer (FDE)', 'Solutions & Delivery', NULL, NULL, 'Work inside customers'' real businesses to build and ship production Agent apps on LeapOpen.'),
  ('modaleap-fde-delivery-engineer', 'zh', 'FDE（交付工程师）', '解决方案与交付', NULL, NULL, '深入客户真实业务，基于 LeapOpen 开发并交付可上线的 Agent 应用。'),
  ('modaleap-fde-delivery-engineer', 'ja', 'FDE（導入エンジニア）', 'ソリューション・導入', NULL, NULL, '顧客の実業務に入り込み、LeapOpen 上で本番運用できる Agent アプリを開発・導入します。'),
  ('modaleap-fde-delivery-engineer', 'ko', 'FDE (딜리버리 엔지니어)', '솔루션·딜리버리', NULL, NULL, '고객의 실제 업무에 깊이 들어가 LeapOpen 기반으로 실서비스 Agent 애플리케이션을 개발·납품합니다.'),
  ('modaleap-fde-delivery-engineer', 'es', 'Forward Deployed Engineer (FDE)', 'Soluciones y entrega', NULL, NULL, 'Trabaja dentro del negocio real del cliente para construir y entregar apps de agentes en producción sobre LeapOpen.'),
  ('modaleap-fde-delivery-engineer', 'pt', 'Forward Deployed Engineer (FDE)', 'Soluções e entrega', NULL, NULL, 'Atue no negócio real do cliente para construir e entregar apps de agentes em produção sobre o LeapOpen.'),
  ('modaleap-fde-delivery-engineer', 'id', 'Forward Deployed Engineer (FDE)', 'Solusi & delivery', NULL, NULL, 'Terjun ke bisnis nyata pelanggan untuk membangun dan mengirim aplikasi Agent siap produksi di LeapOpen.'),
  ('modaleap-fde-delivery-engineer', 'vi', 'Forward Deployed Engineer (FDE)', 'Giải pháp & triển khai', NULL, NULL, 'Đi sâu vào nghiệp vụ thực tế của khách hàng, phát triển và bàn giao ứng dụng Agent chạy thật trên LeapOpen.'),
  ('modaleap-fde-delivery-engineer', 'ar', 'مهندس النشر الميداني (FDE)', 'الحلول والتسليم', NULL, NULL, 'العمل داخل أعمال العملاء الفعلية لتطوير وتسليم تطبيقات وكلاء جاهزة للإنتاج على LeapOpen.'),
